import{_ as r,o as e,c as a,a5 as s}from"./chunks/framework.QWVCgkrI.js";const n="/study/images/graphics/materials-textures-and-shaders.svg",m=JSON.parse('{"title":"マテリアル・テクスチャ・シェーダーの基本","description":"","frontmatter":{"title":"マテリアル・テクスチャ・シェーダーの基本","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"同じ形の箱に木目や金属の見た目を付ける例から、マテリアル、テクスチャ、UV、シェーダー、サンプラーの役割を説明する。","aliases":["マテリアル","material","テクスチャ","texture","UV","テクセル","シェーダー","shader","サンプラー","sampler","フィルタリング","metallic","roughness"],"verification":"Unityのマテリアル・テクスチャ資料、KhronosのglTF仕様、Microsoftの描画パイプライン資料に照合（2026-11-07）"}},"headers":[],"relativePath":"graphics/basics/materials-textures-and-shaders.md","filePath":"graphics/basics/materials-textures-and-shaders.md"}'),i={name:"graphics/basics/materials-textures-and-shaders.md"};function o(d,t,h,l,g,c){return e(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="マテリアル・テクスチャ・シェーダーの基本" tabindex="-1">マテリアル・テクスチャ・シェーダーの基本 <a class="header-anchor" href="#マテリアル・テクスチャ・シェーダーの基本" aria-label="Permalink to &quot;マテリアル・テクスチャ・シェーダーの基本&quot;">​</a></h1><p>同じ形の箱を、木目のある箱や光を反射する金属の箱として描けます。<a href="/study/graphics/basics/models-and-meshes.html">メッシュ</a>が形を表し、<strong>マテリアル</strong>が表面の見え方を指定します。両方のデータを組み合わせて一つの物体を描きます。<a href="https://docs.unity.com/en-us/engine/6000.0/manual/materials-and-shaders/materials/introduction" target="_blank" rel="noreferrer">Unityのマテリアルの説明</a></p><h2 id="表面の設定、参照するデータ、計算するプログラム" tabindex="-1">表面の設定、参照するデータ、計算するプログラム <a class="header-anchor" href="#表面の設定、参照するデータ、計算するプログラム" aria-label="Permalink to &quot;表面の設定、参照するデータ、計算するプログラム&quot;">​</a></h2><p>コードで色ができる流れは、<a href="/study/graphics/shader/shader-first-steps.html">シェーダーの第一歩</a>から追えます。</p><table tabindex="0"><thead><tr><th>名前</th><th>担当すること</th><th>木の箱の例</th></tr></thead><tbody><tr><td><strong>マテリアル</strong></td><td>表面の計算に使う値やデータへの参照、利用するシェーダーなどを指定する。</td><td>茶色、表面の粗さ、木目の画像を設定する。</td></tr><tr><td><strong>テクスチャ</strong></td><td>描画中に参照する、画素状に並んだ値などのデータ。</td><td>木目の画像を保持する。</td></tr><tr><td><strong>シェーダー</strong></td><td>頂点や画面上の領域などを処理するプログラム。</td><td>木目、光、表面の向きなどから色を計算する。</td></tr></tbody></table><p>例えばUnityのマテリアルは、シェーダーへの参照を持ち、そのシェーダーが公開する色やテクスチャなどの値を設定します。マテリアルが含む項目や描画設定の分担は、エンジンや描画方式で変わります。同じシェーダーへ異なる値を渡し、複数の見た目を作ることもできます。<a href="https://docs.unity.com/en-us/engine/6000.0/manual/materials-and-shaders/materials/introduction" target="_blank" rel="noreferrer">Unityのマテリアルの構成</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/overviews-direct3d-11-graphics-pipeline" target="_blank" rel="noreferrer">Microsoftのプログラム可能な描画ステージ</a></p><figure class="study-figure"><img src="'+n+'" alt="マテリアルが色・粗さ・テクスチャなどを指定し、シェーダーが頂点から渡されたUVや光の情報と組み合わせて色を計算する。UVはテクスチャのどこを参照するかを表し、サンプラーは周辺の値の読み方を決める。" width="760" height="476" loading="lazy"><figcaption>ゲームでGPUを使う例で、設定するデータと、処理するプログラムの役割を比べます。<a href="/study/images/graphics/materials-textures-and-shaders.svg" target="_blank" rel="noopener noreferrer">マテリアルとテクスチャの図を拡大</a></figcaption></figure><h2 id="uvは、テクスチャのどこを見るかを表す" tabindex="-1">UVは、テクスチャのどこを見るかを表す <a class="header-anchor" href="#uvは、テクスチャのどこを見るかを表す" aria-label="Permalink to &quot;UVは、テクスチャのどこを見るかを表す&quot;">​</a></h2><p><strong>UV</strong>は、メッシュの表面と2次元のテクスチャを対応付ける座標です。例えば箱の角に「画像のこの位置を使う」というUVを設定します。三角形の内部を描くときは、頂点から渡されたUVを補間して、途中の位置でも対応するテクスチャの値を読めるようにします。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#meshes" target="_blank" rel="noreferrer">glTFの頂点属性とテクスチャ座標</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/d3d10-graphics-programming-guide-rasterizer-stage" target="_blank" rel="noreferrer">Microsoftの頂点属性の補間</a></p><p>画像を0〜1の範囲で参照する例では、<code>(0.5, 0.5)</code>は中央です。範囲の外を繰り返すか、端で止めるかは読み方の設定で決まります。画像の上下の扱いやUVの原点は、形式やAPIの規約と合わせます。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#texture-data" target="_blank" rel="noreferrer">glTFのテクスチャ座標とサンプラー</a></p><p>同じメッシュの場所でも、面ごとに画像の別の位置へ対応付けたいことがあります。UVを切り分ける境界を<strong>シーム</strong>と呼びます。描画用の頂点にはUVも含まれるため、同じ位置にUVの異なる頂点を用意する場合があります。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#meshes" target="_blank" rel="noreferrer">glTFのメッシュの属性</a> · <a href="/study/graphics/mesh/vertex-and-index-input.html">頂点とインデックスの詳細</a></p><h2 id="サンプラーが、値の読み方を決める" tabindex="-1">サンプラーが、値の読み方を決める <a class="header-anchor" href="#サンプラーが、値の読み方を決める" aria-label="Permalink to &quot;サンプラーが、値の読み方を決める&quot;">​</a></h2><p>テクスチャ内の一つの要素を<strong>テクセル</strong>と呼びます。画面に描く位置とテクセルの位置は、常に一対一にはなりません。<strong>サンプラー</strong>には、近くのテクセルを選ぶか、周辺の値を混ぜるかといった<strong>フィルタリング</strong>や、座標が範囲外のときの扱いを指定します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/overviews-direct3d-11-resources-textures-intro" target="_blank" rel="noreferrer">Microsoftのテクセル</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d11/ns-d3d11-d3d11_sampler_desc" target="_blank" rel="noreferrer">サンプラーの設定</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d11/ne-d3d11-d3d11_filter" target="_blank" rel="noreferrer">フィルタリング</a></p><p>遠くにある物体には、元画像より小さい**mip（ミップ）**の画像を使うこともあります。読み取る範囲に合う解像度を選ぶことで、細かな模様のちらつきや読み取り負荷を抑えられます。<a href="https://docs.unity.com/en-us/engine/6000.0/manual/materials-and-shaders/textures/textures-getting-started/textures" target="_blank" rel="noreferrer">Unityのテクスチャとmip</a> · <a href="/study/graphics/texture/texture-streaming-and-mip-residency.html">mipの常駐とストリーミング</a></p><h2 id="テクスチャに入るものは、色のほかにもある" tabindex="-1">テクスチャに入るものは、色のほかにもある <a class="header-anchor" href="#テクスチャに入るものは、色のほかにもある" aria-label="Permalink to &quot;テクスチャに入るものは、色のほかにもある&quot;">​</a></h2><table tabindex="0"><thead><tr><th>データの例</th><th>表すもの</th></tr></thead><tbody><tr><td><strong>ベースカラー</strong></td><td>表面の基本となる色。照明計算への入力として使う。</td></tr><tr><td><strong>ラフネス</strong></td><td>表面の微細な粗さ。反射の広がり方に関係する。</td></tr><tr><td><strong>メタリック</strong></td><td>金属としての反射の扱いを指定する値。</td></tr><tr><td><strong>法線マップ</strong></td><td>細かな表面の向きを表し、陰影の計算に使う。</td></tr></tbody></table><p>色のデータと、粗さや向きなどの数値では、読み取り時に必要な色空間の扱いも異なります。例えばglTFではベースカラーのRGBにsRGBの符号化を使い、粗さや金属度の値には線形の値を使います。保存形式と、シェーダーが期待する値を合わせます。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#materials" target="_blank" rel="noreferrer">glTFのマテリアルと追加テクスチャ</a></p><h2 id="一つのモデルを複数の表面で描く" tabindex="-1">一つのモデルを複数の表面で描く <a class="header-anchor" href="#一つのモデルを複数の表面で描く" aria-label="Permalink to &quot;一つのモデルを複数の表面で描く&quot;">​</a></h2><p>キャラクターの服、肌、金属の装備には、異なるマテリアルを割り当てられます。描画時には、メッシュの部分と対応するマテリアルを組にして扱います。例えばglTFでは、メッシュを構成する各プリミティブがマテリアルを参照できます。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#meshes" target="_blank" rel="noreferrer">glTFのメッシュとマテリアルの対応</a></p><p>画面の色ができるまでの全体は<a href="/study/graphics/basics/light-and-rendered-images.html">光とレンダリングの基本</a>、シェーダーの種類は<a href="/study/graphics/shader/overview.html">シェーダ言語の総論</a>、表面と光の詳しい計算は<a href="/study/graphics/lighting/pbr.html">PBR</a>へ進めます。</p>',20)])])}const u=r(i,[["render",o]]);export{m as __pageData,u as default};
